-- Native ScriptBlox Search Integration via HttpService / API
local HttpService = game:GetService("HttpService")

local function searchScriptBlox(query)
	-- Clear old results
	for _, child in ipairs(ResultsScroll:GetChildren()) do
		if child:IsA("Frame") then
			child:Destroy()
		end
	end

	local success, result = pcall(function()
		local url = "https://scriptblox.com/api/script/search?q=" .. HttpService:UrlEncode(query) .. "&page=1"
		return HttpService:JSONDecode(game:HttpGet(url))
	end)

	if success and result and result.result and result.result.scripts then
		for _, scriptData in ipairs(result.result.scripts) do
			local scriptFrame = Instance.new("Frame", ResultsScroll)
			scriptFrame.Size = UDim2.new(1, -10, 0, 45)
			scriptFrame.BackgroundColor3 = Color3.fromRGB(23, 26, 255)
			scriptFrame.BorderSizePixel = 0

			local titleLabel = Instance.new("TextLabel", scriptFrame)
			titleLabel.Size = UDim2.new(0, 320, 0, 20)
			titleLabel.Position = UDim2.new(0, 5, 0, 2)
			titleLabel.Text = scriptData.title or "Unknown Script"
			titleLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
			titleLabel.TextSize = 12
			titleLabel.TextXAlignment = Enum.TextXAlignment.Left
			titleLabel.BackgroundTransparency = 1
			titleLabel.FontFace = Font.new([[rbxasset://fonts/families/Arimo.json]], Enum.FontWeight.Bold, Enum.FontStyle.Normal)

			local gameLabel = Instance.new("TextLabel", scriptFrame)
			gameLabel.Size = UDim2.new(0, 320, 0, 18)
			gameLabel.Position = UDim2.new(0, 5, 0, 22)
			gameLabel.Text = "Game: " .. (scriptData.game and scriptData.game.name or "Universal")
			gameLabel.TextColor3 = Color3.fromRGB(130, 203, 255)
			gameLabel.TextSize = 10
			gameLabel.TextXAlignment = Enum.TextXAlignment.Left
			gameLabel.BackgroundTransparency = 1
			gameLabel.FontFace = Font.new([[rbxasset://fonts/families/AccanthisADFStd.json]], Enum.FontWeight.Regular, Enum.FontStyle.Normal)

			local loadBtn = Instance.new("TextButton", scriptFrame)
			loadBtn.Size = UDim2.new(0, 85, 0, 35)
			loadBtn.Position = UDim2.new(1, -90, 0, 5)
			loadBtn.Text = "Load to Editor"
			loadBtn.TextSize = 10
			loadBtn.BackgroundColor3 = Color3.fromRGB(19, 0, 137)
			loadBtn.TextColor3 = Color3.fromRGB(130, 203, 255)
			loadBtn.FontFace = Font.new([[rbxasset://fonts/families/AccanthisADFStd.json]], Enum.FontWeight.Regular, Enum.FontStyle.Normal)

			loadBtn.MouseButton1Click:Connect(function()
				LMG2L["TextBox_4"].Text = scriptData.script or "-- No script source available"
				LMG2L["ScriptbloxPage"].Visible = false
				LMG2L["Frame_2"].Visible = true
			end)
		end
	else
		local errLabel = Instance.new("TextLabel", ResultsScroll)
		errLabel.Size = UDim2.new(1, 0, 0, 30)
		errLabel.Text = "No scripts found or API error."
		errLabel.TextColor3 = Color3.fromRGB(0, 0, 0)
		errLabel.TextSize = 14
		errLabel.BackgroundTransparency = 1
	end
end

